import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getSession } from '@/lib/auth';

export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    const session = await getSession();

    // Only Super-Admin can view the global vendor registry
    if (!session || session.role !== 'ADMIN') {
      return NextResponse.json(
        { success: false, error: 'Acces interzis. Rolul de administrator este necesar.' },
        { status: 403 }
      );
    }

    const vendors = await prisma.vendor.findMany({
      orderBy: { createdAt: 'desc' },
      include: {
        user: {
          select: {
            id: true,
            name: true,
            email: true,
            phone: true,
          },
        },
        _count: {
          select: {
            products: true,
          },
        },
        orderItems: {
          select: {
            price: true,
            quantity: true,
            status: true,
          },
        },
      },
    });

    const formattedVendors = vendors.map((v) => {
      // Calculate total revenue generated by this vendor
      const totalSales = v.orderItems.reduce(
        (sum, item) => sum + Number(item.price) * item.quantity,
        0
      );

      return {
        id: v.id,
        userId: v.userId,
        storeName: v.storeName,
        slug: v.slug,
        description: v.description,
        rating: v.rating,
        isVerified: v.isVerified,
        commissionRate: v.commissionRate,
        legalName: v.legalName || 'Nespecificat',
        cui: v.cui || 'Nespecificat',
        regCom: v.regCom || 'Nespecificat',
        iban: v.iban || 'Nespecificat',
        bank: v.bank || 'Nespecificat',
        legalAddress: v.legalAddress || 'Nespecificat',
        contactPerson: v.contactPerson || v.user?.name || 'Nespecificat',
        phone: v.phone || v.user?.phone || 'Nespecificat',
        email: v.user?.email || 'Nespecificat',
        status: v.status || (v.isVerified ? 'ACTIVE' : 'PENDING'),
        productsCount: v._count.products,
        totalSales,
        createdAt: v.createdAt,
      };
    });

    return NextResponse.json({
      success: true,
      vendors: formattedVendors,
    });
  } catch (error) {
    console.error('Error fetching vendors:', error);
    return NextResponse.json(
      { success: false, error: 'Eroare la încărcarea listei de vânzători.' },
      { status: 500 }
    );
  }
}
